const today = new Date();
const start = new Date(today);
start.setDate(start.getDate() - 180);

return [{
  json: {
    start_date: start.toISOString().slice(0, 10),
    end_date: today.toISOString().slice(0, 10),
    generated_at: today.toISOString().slice(0, 16).replace('T', ' ')
  }
}];

// Merge all Oura data sources into unified daily timeline
const readiness = $('💍 Oura Readiness').item.json.data || [];
const sleep     = $('🌙 Oura Sleep').item.json.data || [];
const activity  = $('🏃 Oura Activity').item.json.data || [];
const stress    = $('🧠 Oura Stress').item.json.data || [];
const sessions  = $('💤 Sleep Sessions (HRV)').item.json.data || [];
const fileData  = $('📦 Get Existing health_data.js').item.json;
const generatedAt = $('📅 Set Date Range').item.json.generated_at;

// Decode existing file to preserve Apple Health data
let existing = { stats: {}, timeline: [], workouts: [] };
try {
  const content = Buffer.from(fileData.content, 'base64').toString('utf-8');
  const jsonStr = content.split('const HEALTH_DATA = ')[1].replace(/;\s*$/, '');
  existing = JSON.parse(jsonStr);
} catch(e) { console.log('Starting fresh:', e.message); }

// Index existing Apple Health data by day
const appleByDay = {};
for (const e of existing.timeline || []) {
  if (e.apple) appleByDay[e.day] = e.apple;
}

// Build lookup maps
const readMap = {}; for (const r of readiness) readMap[r.day] = { score: r.score, contributors: r.contributors };
const sleepMap = {}; for (const s of sleep)     sleepMap[s.day] = { score: s.score, contributors: s.contributors };
const actMap = {};  for (const a of activity)   actMap[a.day]  = { steps: a.steps, active_calories: a.active_calories, score: a.score };
const stressMap = {}; for (const s of stress)   stressMap[s.day] = { stress_high: s.stress_high, recovery_high: s.recovery_high };

// HRV from sleep sessions (long_sleep preferred)
const hrvMap = {};
for (const s of sessions) {
  if (!hrvMap[s.day] || (s.type === 'long_sleep' && hrvMap[s.day].type !== 'long_sleep')) {
    hrvMap[s.day] = { avg_hrv: s.average_hrv, avg_hr: s.average_heart_rate, type: s.type };
  }
}

// Collect all days
const allDays = new Set([
  ...Object.keys(readMap), ...Object.keys(sleepMap),
  ...Object.keys(actMap),  ...Object.keys(appleByDay)
]);

// Build timeline
const timeline = [];
for (const day of [...allDays].sort()) {
  const entry = { day };
  if (readMap[day])   entry.oura_readiness = readMap[day];
  if (sleepMap[day])  entry.oura_sleep     = sleepMap[day];
  if (actMap[day])    entry.oura_activity  = actMap[day];
  if (stressMap[day]) entry.oura_stress    = stressMap[day];
  if (hrvMap[day])    entry.oura_sleep_model = hrvMap[day];
  if (appleByDay[day]) entry.apple         = appleByDay[day];
  timeline.push(entry);
}

// Compute summary stats
const ouradays = timeline.filter(e => e.oura_readiness);
const avg = arr => arr.length ? Math.round(arr.reduce((a,b)=>a+b,0)/arr.length*10)/10 : null;

const stats = {
  days_tracked: ouradays.length,
  apple_days_tracked: timeline.filter(e => e.apple).length,
  date_range_start: ouradays[0]?.day || '',
  date_range_end:   ouradays[ouradays.length-1]?.day || '',
  avg_readiness_score: avg(ouradays.map(e=>e.oura_readiness?.score).filter(Boolean)),
  avg_sleep_score:     avg(ouradays.map(e=>e.oura_sleep?.score).filter(Boolean)),
  avg_hrv:             avg(ouradays.map(e=>e.oura_sleep_model?.avg_hrv).filter(Boolean)),
  avg_resting_hr:      avg(ouradays.map(e=>e.oura_sleep_model?.avg_hr).filter(Boolean)),
  oura_updated_at: generatedAt,
  apple_updated_at: existing.stats?.apple_updated_at || null,
  generated_at: generatedAt
};

const payload = { stats, timeline, workouts: existing.workouts || [] };
const jsContent = `// Auto-generated by n8n workflow — ${generatedAt}\nconst HEALTH_DATA = ${JSON.stringify(payload)};\n`;
const encoded = Buffer.from(jsContent).toString('base64');

return [{ json: { content: encoded, sha: fileData.sha, stats, payload } }];

const stats = $('🔀 Merge & Transform Data').item.json.stats;
const aiResponse = $input.item.json;
const insight = aiResponse.content?.[0]?.text || 'No insight generated';
const date = stats.date_range_end;

return [{
  json: {
    subject: `🧬 Health Dashboard — Daily Update ${date}`,
    body: `Daily Health Summary — ${date}\n\n` +
          `📊 Readiness: ${stats.avg_readiness_score}\n` +
          `🌙 Sleep: ${stats.avg_sleep_score}\n` +
          `⚡ HRV: ${stats.avg_hrv}ms\n` +
          `❤️  Resting HR: ${stats.avg_resting_hr}bpm\n\n` +
          `🧬 AI Insight:\n${insight}\n\n` +
          `🔗 Dashboard: https://vandanakarthikeya.github.io/personal-health-dashboard.html`
  }
}];
